import os, json, re
from datetime import datetime, timezone, timedelta

IST = timezone(timedelta(hours=5, minutes=30))
transcript_path = '/Users/lyndonpinto/.gemini/antigravity-ide/brain/01b2b15b-59cf-41b5-848c-8b94e11b6aec/.system_generated/logs/transcript.jsonl'

turns = []
current_turn = None

with open(transcript_path, 'r', encoding='utf-8') as f:
    for line in f:
        try:
            entry = json.loads(line)
            src = entry.get('source')
            typ = entry.get('type')
            content = entry.get('content')
            ts = entry.get('created_at')

            if src == 'USER_EXPLICIT' and typ == 'USER_INPUT':
                # extract text between <USER_REQUEST>
                req_match = re.search(r'<USER_REQUEST>\s*(.*?)\s*</USER_REQUEST>', content, re.DOTALL)
                clean_req = req_match.group(1).strip() if req_match else content.strip()
                if current_turn:
                    turns.append(current_turn)
                current_turn = {
                    'timestamp': ts,
                    'user_request': clean_req,
                    'assistant_responses': [],
                    'tool_calls': []
                }
            elif current_turn and src == 'MODEL' and typ == 'PLANNER_RESPONSE':
                if content:
                    current_turn['assistant_responses'].append(content.strip())
                for tc in entry.get('tool_calls', []):
                    current_turn['tool_calls'].append(tc.get('name'))
        except Exception:
            pass

if current_turn:
    turns.append(current_turn)

print(f'Parsed {len(turns)} complete conversation turns:')
for idx, t in enumerate(turns):
    print(f'Turn {idx+1}: {t[\"user_request\"]} | Responses: {len(t[\"assistant_responses\"])} | Tools: {len(t[\"tool_calls\"])}')
